//! Both real Tamiyo faces through casting, drawing, entry, loyalty and cleanup.
use crate::support::{cite, paid};
use game::{CardDef,Game,Move,ObjId,Target,Zone};
use game::state::{Answer,Choice,Decision};
use ir::{CardType,Color};
use ir::mana::ManaSymbol;
fn tamiyo()->CardDef {let fs=oracle::corpus::load(&oracle::corpus::default_path()).unwrap();let faces=fs.iter().filter(|f|f.name=="Tamiyo, Inquisitive Student // Tamiyo, Seasoned Scholar").collect::<Vec<_>>();let d=CardDef::from_faces(&faces).unwrap();game::play::check(&d).unwrap();d}
fn setup()->Game {let ds=vec![tamiyo(),CardDef::new("Bear","{0}","Creature — Bear","",Some((3,3))).unwrap(),CardDef::new("Study","{0}","Sorcery","Draw three cards.",None).unwrap(),CardDef::new("Green","{G}","Instant","You gain 1 life.",None).unwrap(),CardDef::new("Blue","{U}","Instant","You gain 1 life.",None).unwrap()];let mut g=Game::new(ds,3,20);for p in 0..3{for _ in 0..25{g.put(p,1,Zone::Library);}}g}
fn pass(g:&mut Game){for _ in 0..g.players.len(){g.act(g.decision_maker(g.priority),Move::Pass).unwrap();}}
fn next(g:&mut Game){let t=g.turn;for _ in 0..150{if g.turn!=t{return;}let mv=match &g.decision{Some(Decision::Attackers{..})=>Move::Attack(vec![]),Some(Decision::Blockers{..})=>Move::Block(vec![]),Some(Decision::Discard{player,count})=>Move::Discard(g.players[*player].hand[..*count].to_vec()),None=>Move::Pass,x=>panic!("{x:?}")};g.act(g.decision_maker(g.decision_actor()),mv).unwrap();}panic!("turn did not finish");}
fn student(g:&mut Game)->ObjId {let card=g.put(0,0,Zone::Hand);g.add_mana(0,ManaSymbol::Color(Color::Blue));g.act(0,paid("U",Move::Cast{card,targets:vec![]})).unwrap();pass(g);*g.battlefield.last().unwrap()}
fn study(g:&mut Game){let card=g.put(0,2,Zone::Hand);g.act(0,Move::Cast{card,targets:vec![]}).unwrap();pass(g);}
fn scholar(g:&mut Game)->ObjId {let front=student(g);study(g);assert_eq!(g.stack.len(),1);pass(g);let back=*g.battlefield.last().unwrap();assert_ne!(front,back);assert!(g.obj(back).transformed);back}
#[test]fn r712_14a_third_draw_exiles_then_enters_with_back_characteristics_and_loyalty(){
 let mut g=setup();let t=scholar(&mut g);cite!(["712.14a"]; assert_eq!(g.def(t).unwrap().name(),"Tamiyo, Seasoned Scholar"));cite!(["306.5b"]; assert_eq!(g.obj(t).counters["loyalty"],2));assert!(g.is_a(t,CardType::Planeswalker));assert!(!g.is_a(t,CardType::Creature));cite!(["712.8e"]; assert_eq!(g.obj(t).chars.mana_value,1));assert_eq!(g.obj(t).chars.colors,vec![Color::Green,Color::Blue]);assert!(!g.has(t,"Flying"));assert_eq!(g.players[0].hand.len(),3);assert!(g.exile.is_empty());
 g.move_object(t,Zone::Hand);let hand=*g.players[0].hand.last().unwrap();cite!(["712.8a"]; assert_eq!(g.def(hand).unwrap().name(),"Tamiyo, Inquisitive Student"));assert!(!g.obj(hand).transformed);
}
#[test]fn r608_2h_returned_green_card_uses_last_known_information_then_asks_mana_once(){
 for index in [3,4]{let mut g=setup();let t=scholar(&mut g);g.put_counters(t,"loyalty",1);let card=g.put(0,index,Zone::Graveyard);g.act(0,Move::Activate{source:t,ability:1,targets:vec![vec![Target::Object(card)]],paying:vec![]}).unwrap();assert!(!g.battlefield.contains(&t));pass(&mut g);assert_eq!(g.players[0].hand.len(),4);
 if index==3{cite!(["608.2h"]; case: index; assert!(matches!(g.decision,Some(Decision::Choose{choice:Choice::Mana{..},..}))));let mut copy=g.clone();for g in [&mut g,&mut copy]{cite!(["608.2d"]; refused("the choice is which of the mana offered to add (608.2d)"): g.act(0,Move::Choose(Answer::Mana(vec![ManaSymbol::Colorless]))));g.act(0,Move::Choose(Answer::Mana(vec![ManaSymbol::Color(Color::Red)]))).unwrap();assert_eq!(g.players[0].pool.colors[3],1);assert!(g.stack.is_empty());}assert_eq!(format!("{g:?}"),format!("{copy:?}"));}else{assert!(g.decision.is_none());cite!(["608.2h"]; case: index; assert_eq!(g.players[0].pool.total(),0));}}
}
#[test]fn r107_1a_ultimate_rounds_up_once_then_emblem_removes_cleanup_limit_after_source_dies(){
 let mut g=setup();let t=scholar(&mut g);g.put_counters(t,"loyalty",5);let before=g.players[0].library.len();assert_eq!(before,22);g.draw(0,1);let before=g.players[0].library.len();assert_eq!(before,21);let hand=g.players[0].hand.len();g.act(0,Move::Activate{source:t,ability:2,targets:vec![],paying:vec![]}).unwrap();assert!(!g.battlefield.contains(&t));pass(&mut g);cite!(["107.1a"]; assert_eq!(g.players[0].hand.len(),hand+11));assert_eq!(g.players[0].library.len(),10);cite!(["114.4"]; assert_eq!(g.maximum_hand_size(0),None));assert_eq!(g.maximum_hand_size(1),Some(7));let count=g.players[0].hand.len();next(&mut g);cite!(["514.1", "114.4"]; assert_eq!(g.players[0].hand.len(),count));assert_eq!(g.command.len(),1);
}
#[test]fn r603_7b_delayed_attacks_cover_player_and_planeswalker_until_controllers_next_turn(){
 let mut g=setup();let a=g.put(1,1,Zone::Battlefield);let b=g.put(1,1,Zone::Battlefield);let c=g.put(1,1,Zone::Battlefield);let d=g.put(2,1,Zone::Battlefield);let t=scholar(&mut g);g.act(0,Move::Activate{source:t,ability:0,targets:vec![],paying:vec![]}).unwrap();pass(&mut g);next(&mut g);
 while !matches!(g.decision,Some(Decision::Attackers{..})){g.act(g.priority,Move::Pass).unwrap();}g.act(1,Move::Attack(vec![(a,Target::Player(0)),(b,Target::Object(t)),(c,Target::Player(2))])).unwrap();if let Some(Decision::Order{player,..})=g.decision{g.act(player,Move::Order(vec![0,1])).unwrap();}cite!(["603.7b"]; assert_eq!(g.stack.len(),2));let copy=g.clone();
 for mut branch in [g,copy]{pass(&mut branch);pass(&mut branch);assert_eq!(branch.power(a),Some(2));assert_eq!(branch.power(b),Some(2));assert_eq!(branch.power(c),Some(3));branch.exile(t);next(&mut branch);assert_eq!(branch.power(a),Some(3));while !matches!(branch.decision,Some(Decision::Attackers{..})){branch.act(branch.priority,Move::Pass).unwrap();}branch.act(2,Move::Attack(vec![(d,Target::Player(0))])).unwrap();cite!(["603.7b"]; assert_eq!(branch.stack.len(),1));pass(&mut branch);assert_eq!(branch.power(d),Some(2));next(&mut branch);assert_eq!(branch.active,0);next(&mut branch);while !matches!(branch.decision,Some(Decision::Attackers{..})){branch.act(branch.priority,Move::Pass).unwrap();}branch.act(1,Move::Attack(vec![(a,Target::Player(0))])).unwrap();assert!(branch.stack.is_empty(),"subscription expired at the start of player zero next turn");}
}
#[test]fn r508_1_investigate_attack_creates_a_clue_whose_draw_can_be_the_third(){
 let mut g=setup();let t=student(&mut g);next(&mut g);next(&mut g);next(&mut g);while !matches!(g.decision,Some(Decision::Attackers{..})){g.act(g.priority,Move::Pass).unwrap();}g.act(0,Move::Attack(vec![(t,Target::Player(1))])).unwrap();pass(&mut g);let clue=*g.battlefield.iter().find(|o|g.obj(**o).token()).unwrap();cite!(["701.16a"]; assert_eq!(g.obj(clue).chars.name,"Clue Token"));g.draw(0,1);g.players[0].pool.colorless=2;g.act(0,paid("CC", Move::Activate{source:clue,ability:0,targets:vec![],paying:vec![]})).unwrap();pass(&mut g);assert_eq!(g.stack.len(),1);assert!(!g.battlefield.contains(&clue));pass(&mut g);let back=*g.battlefield.last().unwrap();cite!(["712.14a"]; assert!(g.obj(back).transformed));cite!(["506.4"]; assert!(!g.combat.attacking(back)));assert_eq!(g.obj(back).counters["loyalty"],2);
}
#[test]fn r712_14a_controlled_student_returns_transformed_to_its_owner(){
 let mut g=setup();let t=student(&mut g);let control=CardDef::new("Control","{0}","Instant","Gain control of target creature until end of turn.",None).unwrap();let draw=CardDef::new("Together","{0}","Sorcery","Each player draws three cards.",None).unwrap();for d in [&control,&draw]{game::play::check(d).unwrap();}std::sync::Arc::make_mut(&mut g.defs).extend([control,draw]);let take=g.put(1,5,Zone::Hand);g.act(0,Move::Pass).unwrap();g.act(1,Move::Cast{card:take,targets:vec![vec![Target::Object(t)]]}).unwrap();pass(&mut g);assert_eq!(g.controller(t),1);let card=g.put(0,6,Zone::Hand);g.act(0,Move::Cast{card,targets:vec![]}).unwrap();pass(&mut g);assert_eq!(g.stack.len(),1);cite!(["603.3a"]; assert_eq!(g.obj(g.stack[0]).controller,1));pass(&mut g);let back=*g.battlefield.last().unwrap();assert!(g.obj(back).transformed);cite!(["110.2"]; assert_eq!((g.obj(back).owner,g.controller(back)),(0,0)));assert_eq!(g.obj(back).counters["loyalty"],2);
}
#[test]fn r400_7_pending_third_draw_does_not_transform_a_new_incarnation(){
 let mut g=setup();let t=student(&mut g);study(&mut g);g.exile(t);let card=g.exile[0];g.move_object(card,Zone::Hand);pass(&mut g);cite!(["400.7"]; assert!(g.battlefield.is_empty()));assert!(g.exile.is_empty());assert_eq!(g.players[0].hand.len(),4);
}
#[test]fn r712_14a_one_faced_copy_exiles_itself_but_cannot_return_transformed(){
 let mut g=setup();let front=student(&mut g);let clone=CardDef::new("Clone","{0}","Creature — Shapeshifter","You may have this creature enter as a copy of any creature on the battlefield.",Some((0,0))).unwrap();game::play::check(&clone).unwrap();std::sync::Arc::make_mut(&mut g.defs).push(clone);let c=g.put(0,5,Zone::Hand);g.act(0,Move::Cast{card:c,targets:vec![]}).unwrap();pass(&mut g);g.act(0,Move::Choose(Answer::Objects(vec![front]))).unwrap();
 let copied=*g.battlefield.iter().find(|o|g.obj(**o).card==Some(5)).unwrap();g.act(0,Move::Choose(Answer::Objects(vec![copied]))).unwrap();study(&mut g);assert_eq!(g.stack.len(),1);pass(&mut g);assert!(g.battlefield.is_empty());cite!(["712.14a"]; assert_eq!(g.exile.len(),1));assert_eq!(g.def(g.exile[0]).unwrap().name(),"Clone");
}
#[test]fn r712_14a_entry_choices_and_replacements_read_the_back_face_before_it_enters(){
 let front=CardDef::new("Front","{0}","Creature","{0}: Exile this creature, then return it to the battlefield transformed under its owner's control.",Some((1,1))).unwrap();let back=CardDef::planeswalker("Back","","Planeswalker — Tamiyo","As this planeswalker enters, choose a color.\n+1: You gain 1 life.",2).unwrap();let face=CardDef::transforming(front,back).unwrap();game::play::check(&face).unwrap();let replacement=CardDef::new("Counters","{0}","Enchantment","Planeswalkers you control enter tapped.",None).unwrap();game::play::check(&replacement).unwrap();let mut g=Game::new(vec![face,replacement],2,20);let f=g.put(0,0,Zone::Battlefield);g.put(0,1,Zone::Battlefield);g.act(0,Move::Activate{source:f,ability:0,targets:vec![],paying:vec![]}).unwrap();pass(&mut g);cite!(["614.12"]; assert!(matches!(g.decision,Some(Decision::Choose{choice:Choice::Value(_),..}))));let mut copy=g.clone();for g in [&mut g,&mut copy]{g.act(0,Move::Choose(Answer::Value(game::binding::Value::Color(Color::Blue)))).unwrap();let b=*g.battlefield.last().unwrap();assert!(g.obj(b).transformed);cite!(["306.5b"]; assert_eq!(g.obj(b).counters["loyalty"],2));cite!(["614.12"]; assert!(g.obj(b).tapped));assert_eq!(g.def(b).unwrap().name(),"Back");}assert_eq!(format!("{g:?}"),format!("{copy:?}"));
}
#[test]fn r107_1a_ambiguous_rounding_and_unsupported_hand_size_assignments_remain_refused(){

 for (kind,text) in [("Sorcery","Draw cards equal to half the number of cards in your library."),("Enchantment","Your maximum hand size is five.")]{let d=CardDef::new("Boundary","{0}",kind,text,None).unwrap();crate::support::refused(game::play::check(&d).map_err(|e|e.0),if kind=="Sorcery" {"amount: Half"} else {"ability on a permanent: sentence: MaxHandSize"});}
}
#[test]fn r114_4_static_hand_size_rules_follow_membership_and_emblems_use_the_same_reader(){
 let rule=CardDef::new("Hand rule","{0}","Artifact","You have no maximum hand size.",None).unwrap();let emblem=CardDef::new("Emblem","{0}","Sorcery","You get an emblem with \"You have no maximum hand size.\"",None).unwrap();let null=CardDef::new("Null","{0}","Instant","Target artifact loses all abilities until end of turn.",None).unwrap();for d in [&rule,&emblem,&null]{game::play::check(d).unwrap();}let mut g=Game::new(vec![rule,emblem,null],2,20);let artifact=g.put(0,0,Zone::Battlefield);assert_eq!(g.maximum_hand_size(0),None);let spell=g.put(0,2,Zone::Hand);g.act(0,Move::Cast{card:spell,targets:vec![vec![Target::Object(artifact)]]}).unwrap();pass(&mut g);cite!(["402.2"]; assert_eq!(g.maximum_hand_size(0),Some(7)));let spell=g.put(0,1,Zone::Hand);g.act(0,Move::Cast{card:spell,targets:vec![]}).unwrap();pass(&mut g);g.exile(artifact);cite!(["114.4"]; assert_eq!(g.maximum_hand_size(0),None));assert_eq!(g.maximum_hand_size(1),Some(7));
}
#[test]fn r712_114_managed_transformation_and_ultimate_clone_without_retaining_departed_sources(){
 use game::simulation::Simulation;
 fn respond(s:&mut Simulation,m:Move){let r=s.request().unwrap().unwrap().clone();s.respond(r.id,r.player,m).unwrap();}
 fn resolve(s:&mut Simulation){for _ in 0..3{respond(s,Move::Pass);}}
 let mut g=setup();let front=student(&mut g);let add=CardDef::new("Loyalty","{0}","Sorcery","Put five loyalty counters on target planeswalker.",None).unwrap();game::play::check(&add).unwrap();std::sync::Arc::make_mut(&mut g.defs).push(add);let loyalty=g.put(0,5,Zone::Hand);let draw=g.put(0,2,Zone::Hand);let mut sim=Simulation::new(g);respond(&mut sim,Move::Cast{card:draw,targets:vec![]});resolve(&mut sim);assert_eq!(sim.game().unwrap().stack.len(),1);let fork=sim.clone();
 for mut s in [sim,fork]{resolve(&mut s);let back=*s.game().unwrap().battlefield.last().unwrap();assert_ne!(front,back);respond(&mut s,Move::Cast{card:loyalty,targets:vec![vec![Target::Object(back)]]});resolve(&mut s);respond(&mut s,Move::Activate{source:back,ability:2,targets:vec![],paying:vec![]});resolve(&mut s);assert_eq!(s.game().unwrap().maximum_hand_size(0),None);let turn=s.game().unwrap().turn;for _ in 0..200{let g=s.game().unwrap();if g.turn>=turn+3{break;}let mv=match &g.decision{Some(Decision::Attackers{..})=>Move::Attack(vec![]),Some(Decision::Discard{player,count})=>{assert_ne!(*player,0);Move::Discard(g.players[*player].hand[..*count].to_vec())},None=>Move::Pass,x=>panic!("{x:?}")};respond(&mut s,mv);}let g=s.game().unwrap();assert!(g.get_object(front).is_none());assert!(g.get_object(back).is_none());cite!(["114.2"]; assert_eq!(g.command.len(),1));cite!(["114.4"]; assert_eq!(g.maximum_hand_size(0),None));}
}

#[test]fn r712_14a_transformed_entry_checks_the_entering_face_for_a_nonpermanent_front(){
 let front=CardDef::new("Front spell","{0}","Instant","You gain 1 life.",None).unwrap();let back=CardDef::new("Back creature","","Creature","",Some((4,4))).unwrap();let pair=CardDef::transforming(front,back).unwrap();let bring=CardDef::new("Bring","{0}","Sorcery","Return target card from your graveyard to the battlefield transformed.",None).unwrap();for d in [&pair,&bring]{game::play::check(d).unwrap();}let mut g=Game::new(vec![pair,bring],2,20);let card=g.put(0,0,Zone::Graveyard);let spell=g.put(0,1,Zone::Hand);g.act(0,Move::Cast{card:spell,targets:vec![vec![Target::Object(card)]]}).unwrap();pass(&mut g);let back=g.battlefield[0];cite!(["712.14a"]; assert!(g.obj(back).transformed));cite!(["712.14a"]; assert_eq!(g.power(back),Some(4)));assert_eq!(g.def(back).unwrap().name(),"Back creature");
}
